package com.example.starter.curtailment.common;

import java.time.Instant;
import java.time.LocalDateTime;
import java.time.ZoneOffset;

/**
 * UTC 时间换算：数据库 DATETIME 列一律按 UTC 解释，应用层对外使用 Instant。
 */
public final class UtcTimes {

    private UtcTimes() {
    }

    public static LocalDateTime toUtcDateTime(Instant instant) {
        return LocalDateTime.ofInstant(instant, ZoneOffset.UTC);
    }

    public static Instant toInstant(LocalDateTime utcDateTime) {
        return utcDateTime == null ? null : utcDateTime.toInstant(ZoneOffset.UTC);
    }
}

package com.example.starter.curtailment.common;

import com.example.starter.curtailment.error.ApiException;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * 入参校验工具：所有失败均抛出 400 语义的 ApiException。
 */
public final class Check {

    /** 功率小数位上限。 */
    public static final int POWER_SCALE = 3;

    private Check() {
    }

    public static String requireText(String value, String field) {
        if (value == null || value.isBlank()) {
            throw ApiException.badRequest(field + " 不能为空");
        }
        return value.trim();
    }

    public static Instant requireTime(Instant value, String field) {
        if (value == null) {
            throw ApiException.badRequest(field + " 不能为空，须为 UTC 时间");
        }
        return value;
    }

    public static void requireInterval(Instant from, Instant to, String fromField, String toField) {
        requireTime(from, fromField);
        requireTime(to, toField);
        if (!from.isBefore(to)) {
            throw ApiException.badRequest(fromField + " 必须早于 " + toField);
        }
    }

    /**
     * 解析十进制功率字符串：最多 3 位小数；positive 为真时必须大于零。
     */
    public static BigDecimal parsePower(String raw, String field, boolean positive) {
        String text = requireText(raw, field);
        BigDecimal value;
        try {
            value = new BigDecimal(text);
        } catch (NumberFormatException ex) {
            throw ApiException.badRequest(field + " 必须是十进制数字");
        }
        if (value.scale() > POWER_SCALE) {
            throw ApiException.badRequest(field + " 最多 " + POWER_SCALE + " 位小数");
        }
        if (positive && value.signum() <= 0) {
            throw ApiException.badRequest(field + " 必须大于零");
        }
        return value;
    }

    /** 输出功率字符串：去除多余尾零，保持十进制可读形式。 */
    public static String formatPower(BigDecimal value) {
        return value.stripTrailingZeros().toPlainString();
    }
}

package com.example.starter.curtailment.idempotency;

/**
 * 已记录的幂等命令。
 *
 * @param operation      操作类型
 * @param fingerprint    请求参数指纹
 * @param responseStatus 首次成功的 HTTP 状态；未完成时为 null
 * @param responseBody   首次成功的响应 JSON；未完成时为 null
 */
public record StoredCommand(String operation, String fingerprint, Integer responseStatus, String responseBody) {
}

package com.example.starter.curtailment.idempotency;

import com.example.starter.curtailment.common.UtcTimes;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

import java.time.Instant;
import java.util.Optional;

/**
 * 幂等命令记录存取：commandKey 主键保证同键并发只有一份记录。
 */
@Repository
public class IdempotentCommandRepository {

    private final JdbcTemplate jdbc;

    public IdempotentCommandRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public Optional<StoredCommand> findByKey(String commandKey) {
        return jdbc.query(
                        "SELECT operation, fingerprint, response_status, response_body FROM idempotent_command WHERE command_key = ?",
                        (rs, rowNum) -> new StoredCommand(
                                rs.getString("operation"),
                                rs.getString("fingerprint"),
                                (Integer) rs.getObject("response_status"),
                                rs.getString("response_body")),
                        commandKey)
                .stream()
                .findFirst();
    }

    /** 锁读：用于并发同键插入冲突后读取已提交的首次结果。 */
    public Optional<StoredCommand> findByKeyForUpdate(String commandKey) {
        return jdbc.query(
                        "SELECT operation, fingerprint, response_status, response_body FROM idempotent_command WHERE command_key = ? FOR UPDATE",
                        (rs, rowNum) -> new StoredCommand(
                                rs.getString("operation"),
                                rs.getString("fingerprint"),
                                (Integer) rs.getObject("response_status"),
                                rs.getString("response_body")),
                        commandKey)
                .stream()
                .findFirst();
    }

    public void insert(String commandKey, String operation, String fingerprint, Instant createdAt) {
        jdbc.update(
                "INSERT INTO idempotent_command (command_key, operation, fingerprint, created_at_utc) VALUES (?, ?, ?, ?)",
                commandKey, operation, fingerprint, UtcTimes.toUtcDateTime(createdAt));
    }

    public void complete(String commandKey, int responseStatus, String responseBody) {
        jdbc.update(
                "UPDATE idempotent_command SET response_status = ?, response_body = ? WHERE command_key = ?",
                responseStatus, responseBody, commandKey);
    }
}

