    }

    @Test
    void suspendLifecycle() throws Exception {
        createCommitment("cmd-c1", "cm-1", "site-1", FROM, TO, "10");

        postJson("/api/commitments/cm-1/suspend", "{\"commandKey\":\"cmd-s1\"}")
                .andExpect(status().isOk())
